import fs from 'node:fs';import path from 'node:path';import {randomUUID,createHash} from 'node:crypto';
export const digest=x=>createHash('sha256').update(typeof x==='string'?x:JSON.stringify(x)).digest('hex');
// Render restarts can reuse PID 1. Linux start-time + boot identity distinguishes a
// dead prior owner from a live owner. Unknown identity remains fail-closed.
export function processTag(pid=process.pid,read=fs.readFileSync,platform=process.platform){if(platform!=='linux')return null;try{const stat=read('/proc/'+pid+'/stat','utf8'),fields=stat.slice(stat.lastIndexOf(')')+2).trim().split(/\s+/),start=fields[19],boot=read('/proc/sys/kernel/random/boot_id','utf8').trim();if(!/^\d+$/.test(start)||!boot)return null;return boot+':'+start;}catch{return null;}}
export class JournalError extends Error {constructor(code,status=429){super(code);this.code=code;this.status=status;}}
export class Journal {
 constructor(dir,config){this.dir=dir;this.config=config;fs.mkdirSync(dir,{recursive:true});this.owner=path.join(dir,'owner.lock');this.nonce=randomUUID();
  try{this.fd=fs.openSync(this.owner,'wx');}catch(e){if(e.code!=='EEXIST')throw e;let old;try{old=JSON.parse(fs.readFileSync(this.owner));}catch{throw new JournalError('JOURNAL_OWNER_INVALID',503);}if(!Number.isSafeInteger(old.pid)||old.pid<1||typeof old.nonce!=='string')throw new JournalError('JOURNAL_OWNER_INVALID',503);let alive=true;try{process.kill(old.pid,0);}catch(e){if(e.code==='ESRCH')alive=false;}const tag=processTag(old.pid);if(alive&&typeof old.processTag==='string'&&tag&&tag!==old.processTag)alive=false;if(alive)throw new JournalError('JOURNAL_ALREADY_OWNED',503);fs.renameSync(this.owner,this.owner+'.stale-'+randomUUID());this.fd=fs.openSync(this.owner,'wx');}
  fs.writeSync(this.fd,JSON.stringify({pid:process.pid,nonce:this.nonce,processTag:processTag()}));fs.fsyncSync(this.fd);this.file=path.join(dir,'requests.ndjson');this.rows=new Map();
  try{if(fs.existsSync(this.file)){const raw=fs.readFileSync(this.file,'utf8');if(raw&&!raw.endsWith('\n'))throw new JournalError('JOURNAL_TRUNCATED',503);for(const line of raw.split('\n').filter(Boolean)){const event=JSON.parse(line);this.apply(event);}}}catch(e){this.close();throw new JournalError('JOURNAL_INVALID_FAIL_CLOSED',503);}
 }
 apply(e){if(e.type==='reserve'){if(this.rows.has(e.id)||!Number.isSafeInteger(e.reservedNanoUsd)||e.reservedNanoUsd<0)throw Error('INVALID_RESERVATION');this.rows.set(e.id,{...e,state:'usage-unknown',usageState:'unknown',debitNanoUsd:e.reservedNanoUsd});}else if(e.type==='finish'){const row=this.rows.get(e.id);if(!row||!Number.isSafeInteger(e.debitNanoUsd)||e.debitNanoUsd<0)throw Error('INVALID_SETTLEMENT');Object.assign(row,e);}else throw Error('INVALID_EVENT');}
 append(e){const fd=fs.openSync(this.file,'a');try{fs.writeSync(fd,JSON.stringify(e)+'\n');fs.fsyncSync(fd);}finally{fs.closeSync(fd);}this.apply(e);}
 summary(){const rows=[...this.rows.values()];return {attempts:rows.length,estimatedDebitNanoUsd:rows.reduce((n,r)=>n+r.debitNanoUsd,0),unknownUsage:rows.filter(r=>r.usageState!=='known').length,budgetNanoUsd:this.config.budgetNanoUsd,remainingEstimatedNanoUsd:Math.max(0,this.config.budgetNanoUsd-rows.reduce((n,r)=>n+r.debitNanoUsd,0)),providerBillingHardCap:false};}
 reserve({id,requestHash,inputHash,reservedNanoUsd,estimatedInputTokens,executionMode='offline-unit',at=Date.now()}){if(this.rows.has(id))throw new JournalError('DUPLICATE_REQUEST',409);const rows=[...this.rows.values()];if(rows.some(r=>r.requestHash===requestHash&&at-r.at<this.config.duplicateWindowMs))throw new JournalError('DUPLICATE_INPUT_COOLDOWN',409);if(rows.length>=this.config.maxRequests)throw new JournalError('REQUEST_LIMIT_REACHED');if(this.summary().estimatedDebitNanoUsd+reservedNanoUsd>this.config.budgetNanoUsd)throw new JournalError('ESTIMATED_BUDGET_EXHAUSTED');this.append({type:'reserve',id,requestHash,inputHash,reservedNanoUsd,estimatedInputTokens,executionMode,externalAttempt:executionMode==='live',at});}
 finish(id,{state,error,httpStatus,usage,responseHash}){const row=this.rows.get(id);if(!row)throw new JournalError('RESERVATION_NOT_FOUND',503);const valid=usage&&Number.isSafeInteger(usage.prompt_tokens)&&usage.prompt_tokens>=0&&Number.isSafeInteger(usage.completion_tokens)&&usage.completion_tokens>=0;
  const calculated=valid?usage.prompt_tokens*this.config.inputNanoUsdPerToken+usage.completion_tokens*this.config.outputNanoUsdPerToken:row.reservedNanoUsd;
  if(!Number.isSafeInteger(calculated))throw new JournalError('USAGE_COST_INVALID',503);
  this.append({type:'finish',id,state,error,httpStatus,usageState:valid?'known':'unknown',usage:valid?{prompt_tokens:usage.prompt_tokens,completion_tokens:usage.completion_tokens}:null,debitNanoUsd:calculated,responseHash,finishedAt:Date.now(),estimateExceeded:valid&&calculated>row.reservedNanoUsd});}
 close(){if(this.closed)return;this.closed=true;if(this.fd!==undefined)fs.closeSync(this.fd);try{if(JSON.parse(fs.readFileSync(this.owner)).nonce===this.nonce)fs.unlinkSync(this.owner);}catch{}}
}
